                      ...p, promptTokens: parseInt(e.detail.value!, 10) || 0,
                      totalTokens: (parseInt(e.detail.value!, 10) || 0) + p.completionTokens,
                    } : null)}
                  />
                </div>
                <div className="factoryrunusage-field-group">
                  <IonInput
                    fill="outline"
                    label="Completion Tokens *"
                    labelPlacement="floating"
                    type="number"
                    value={selectedUsage.completionTokens}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setSelectedUsage(p => p ? {
                      ...p, completionTokens: parseInt(e.detail.value!, 10) || 0,
                      totalTokens: p.promptTokens + (parseInt(e.detail.value!, 10) || 0),
                    } : null)}
                  />
                </div>
                <div className="factoryrunusage-field-group">
                  <IonInput
                    fill="outline"
                    label="Cost USD *"
                    labelPlacement="floating"
                    type="number"
                    value={selectedUsage.costUSD}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setSelectedUsage(p => p ? { ...p, costUSD: parseFloat(e.detail.value!) || 0 } : null)}
                  />
                </div>
                <div className="factoryrunusage-field-group">
                  <IonDatetimeButton datetime="editDatetime"></IonDatetimeButton>
                  <IonModal keepContentsMounted={true}>
                    <IonDatetime
                      id="editDatetime"
                      value={selectedUsage.timestamp}
                      onIonChange={(e: CustomEvent<DatetimeChangeEventDetail>) => setSelectedUsage(p => p ? { ...p, timestamp: e.detail.value as string } : null)}
                    ></IonDatetime>
                  </IonModal>
                </div>
              </div>
            )}
            <IonButton expand="block" onClick={handleUpdateUsage} className="ion-margin-top" disabled={saving}>
              {saving ? <IonSpinner name="dots" /> : 'Update'}
            </IonButton>
          </IonContent>
        </IonModal>

        {/* Delete Alert */}
        <IonAlert
          isOpen={!!usageToDelete}
          onDidDismiss={() => setUsageToDelete(null)}
          header={'Confirm Delete'}
          message={`Are you sure you want to delete the usage entry for reference "${usageToDelete?.factoryRunRef}"?`}
          buttons={[
            { text: 'Cancel', role: 'cancel' },
            { text: 'Delete', handler: handleDeleteUsage, cssClass: 'danger' },
          ]}
        />
      </IonContent>
    </IonPage>
  );
};

export default FactoryRunUsagePage;
